function drawCaptcha(){captchaCode='';var s='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';for(var i=0;i<4;i++)captchaCode+=s[Math.floor(Math.random()*s.length)];var c=$('captchaCanvas');if(!c)return;var x=c.getContext('2d');x.clearRect(0,0,c.width,c.height);x.fillStyle='#f0edf7';x.fillRect(0,0,c.width,c.height);for(var i=0;i<6;i++){x.strokeStyle='hsl('+Math.random()*360+',50%,70%)';x.lineWidth=1;x.beginPath();x.moveTo(Math.random()*c.width,Math.random()*c.height);x.lineTo(Math.random()*c.width,Math.random()*c.height);x.stroke();}x.textBaseline='middle';for(var i=0;i<captchaCode.length;i++){x.fillStyle='hsl('+(Math.random()*60+220)+',70%,35%)';x.font='bold 26px "Courier New",monospace';x.fillText(captchaCode[i],12+i*24+Math.random()*6,22+Math.random()*6);}}
