function fakeEmail(qq){return'qq'+qq.trim()+'@qq.local';}
async function handleLogin(){var errEl=$('loginErr'),qqEl=$('loginQQ'),passEl=$('loginPass'),btn=$('mainBtn'),bt=$('btnText');if(!qqEl||!passEl){toast('页面加载异常');return;}var qq=qqEl.value.trim(),pass=passEl.value;if(!qq){if(errEl)errEl.textContent='请输入QQ号';return;}if(!/^\d{5,12}$/.test(qq)){if(errEl)errEl.textContent='请输入正确的QQ号';return;}if(!pass){if(errEl)errEl.textContent='请输入密码';return;}if(pass.length<6){if(errEl)errEl.textContent='密码至少6位';return;}if(errEl)errEl.textContent='';var email=fakeEmail(qq);if(btn)btn.disabled=true;if(bt)bt.innerHTML='登录中…';try{if(isReg2){var nameEl=$('regName'),p2El=$('regPass2'),invEl=$('regInvite'),capEl=$('regCaptcha');var name=nameEl?nameEl.value.trim():'',p2=p2El?p2El.value:'',inv=invEl?invEl.value.trim():'';if(!name||name.length<2){if(errEl)errEl.textContent='用户名至少2个字';if(btn)btn.disabled=false;if(bt)bt.textContent='注 册';return;}if(pass!==p2){if(errEl)errEl.textContent='两次密码不一致';if(btn)btn.disabled=false;if(bt)bt.textContent='注 册';return;}if(!captchaCode||!capEl||capEl.value.trim().toUpperCase()!==captchaCode){if(errEl)errEl.textContent='验证码错误';drawCaptcha();if(btn)btn.disabled=false;if(bt)bt.textContent='注 册';return;}var r=await api('/auth/v1/signup',{method:'POST',body:JSON.stringify({email:email,password:pass,data:{nickname:name,qq:qq}})});if(r&&r.access_token){localStorage.setItem('sb_token',r.access_token);localStorage.setItem('sb_refresh',r.refresh_token);localStorage.setItem('sb_user',JSON.stringify(r.user));await afterLogin(r.user);if(inv)dbR('apply_invite',{p_invite_code:inv.toUpperCase()}).then(function(x){if(x==='OK')toast('🎉邀请成功+25硬币');}).catch(function(){});}else{if(errEl)errEl.textContent='注册失败：该QQ号可能已注册';}}else{var r2=await api('/auth/v1/token?grant_type=password',{method:'POST',body:JSON.stringify({email:email,password:pass})});if(r2&&r2.access_token){localStorage.setItem('sb_token',r2.access_token);localStorage.setItem('sb_refresh',r2.refresh_token);localStorage.setItem('sb_user',JSON.stringify(r2.user));afterLogin(r2.user);}else{if(errEl)errEl.textContent='登录失败：QQ号或密码错误，未注册请先注册';}}}catch(e){if(errEl)errEl.textContent='操作失败：'+e.message;}if(btn)btn.disabled=false;if(bt)bt.textContent=isReg2?'注 册':'登 录';}
