async function loadMe(){if(!me)return;var u=me;var folN=await api('/rest/v1/followers?following_id=eq.'+u.id+'&select=id').catch(function(){return[];});var fanN=await api('/rest/v1/followers?follower_id=eq.'+u.id+'&select=id').catch(function(){return[];});var goodN=await api('/rest/v1/tips?select=id&to_user=eq.'+u.id+'&kind=eq.good').catch(function(){return[];});var pct=Math.min(100,Math.round((u.exp-expLv(u.level))/(expLv(u.level+1)-expLv(u.level))*100));var tag=u.role==='admin'?'<span class="tag-admin">管理</span>':'';var credit=u.role==='admin'?'':'<span style="font-size:10px;color:#6A5ACD;margin-left:6px">💯'+u.credit+'</span>';var mp=$('meProfile');if(mp)mp.innerHTML='<div class="me-card" onclick="openUser(\''+u.id+'\')"><div class="me-avatar">'+(u.avatar_url?'<img src="'+esc(u.avatar_url)+'">':esc((u.nickname||'友')[0]))+'</div><div style="flex:1"><div class="me-name">'+esc(u.nickname)+tag+credit+'</div><div class="pt-exp"><i style="width:'+Math.max(4,pct)+'%"></i></div><div class="pt-exp-t">Lv'+u.level+'·'+u.exp+'/'+expLv(u.level+1)+'</div></div><div class="me-arrow">›</div></div>';var ac=$('meAccount');if(ac)ac.innerHTML='<div class="acc-item" onclick="goFriends(\'following\')"><div class="acc-num" style="color:#ff9500">🪙'+u.coins+'</div><div class="acc-label">硬币</div></div><div class="acc-item" onclick="goFriends(\'following\')"><div class="acc-num" style="color:#7B68EE">'+(folN?folN.length:0)+'</div><div class="acc-label">关注</div></div><div class="acc-item" onclick="goFriends(\'fans\')"><div class="acc-num" style="color:#6A5ACD">'+(fanN?fanN.length:0)+'</div><div class="acc-label">粉丝</div></div><div class="acc-item"><div class="acc-num" style="color:#F5A623">'+(goodN?goodN.length:0)+'</div><div class="acc-label">好评</div></div>';var hb=$('meHbar');if(hb)hb.innerHTML=HBAR.filter(function(g){return g[2]!=='adminPage'||(me&&me.role==='admin');}).map(function(g){return g[2]==='logout'?'<div class="hbar-item" onclick="logout()"><div class="hi">'+g[0]+'</div><div class="ht">'+g[1]+'</div></div>':'<div class="hbar-item" onclick="goPage(\''+g[2]+'\')"><div class="hi">'+g[0]+'</div><div class="ht">'+g[1]+'</div></div>';}).join('');var ta=$('topAvatar');if(ta){ta.textContent=u.nickname?u.nickname[0]:'友';if(u.avatar_url)ta.innerHTML='<img src="'+esc(u.avatar_url)+'">';}}
