var showGood=function(u,i){return'<div class="rank-item"><div class="rank-no '+(i<3?'top'+(i+1):'')+'">'+(i+1)+'</div><div style="width:30px;height:30px;border-radius:50%;background:#eee;line-height:30px;text-align:center;overflow:hidden;flex-shrink:0;margin-left:6px;cursor:pointer" onclick="openUser(\''+u.uid+'\')">'+(u.avatar_url?'<img src="'+esc(u.avatar_url)+'" style="width:100%;height:100%;object-fit:cover">':esc((u.nickname||'友')[0]))+'</div><div style="flex:1;margin-left:8px;cursor:pointer" onclick="openUser(\''+u.uid+'\')"><div style="font-size:13px">'+esc(u.nickname)+(u.role==='admin'?'<span class="tag-admin">管理</span>':'')+'</div><div style="font-size:10px;color:#999;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+esc(u.bio||'')+'</div></div><div style="font-size:13px;color:#ff9500;font-weight:600">❤️'+u.good_total+'</div></div>';};
