function pickRing(el,i){pomoRing=i;document.querySelectorAll('#ringOptions .chip').forEach(function(x){x.classList.remove('on');});el.classList.add('on');}
function pomoStart(){var b=$('pomoBtn');if(!b)return;if(pomoT){clearInterval(pomoT);pomoT=null;b.textContent='继续';var ps=$('pomoState');if(ps)ps.textContent='已暂停';return;}var dd=parseInt(($('pomoD')||{}).value)||0,h=parseInt(($('pomoH')||{}).value)||0,m=parseInt(($('pomoM')||{}).value)||0,s=parseInt(($('pomoS')||{}).value)||0;if(m>60)m=60;if(s>60)s=60;pomoL=dd*86400+h*3600+m*60+s;if(pomoL<=0){toast('请设置时间');return;}b.textContent='暂停';var ps2=$('pomoState');if(ps2)ps2.textContent='倒计时中…';pomoT=setInterval(function(){pomoL--;if(pomoL<=0){clearInterval(pomoT);pomoT=null;b.textContent='开始';var ps3=$('pomoState');if(ps3)ps3.textContent='⏰时间到！';try{if(navigator.vibrate)navigator.vibrate([200,100,200,100,200]);}catch(e){}toast('⏰时间到！');return;}pomoRender();},1000);}
function pomoReset(){if(pomoT){clearInterval(pomoT);pomoT=null;}var b=$('pomoBtn');if(b)b.textContent='开始';var ps=$('pomoState');if(ps)ps.textContent='自定义时间';pomoL=0;try{pomoRender();}catch(e){}}
function pomoRender(){var pt=$('pomoTime');if(!pt)return;var dd=Math.floor(pomoL/86400),h=Math.floor(pomoL%86400/3600),m=Math.floor(pomoL%3600/60),s=pomoL%60;pt.textContent=(dd>0?dd+'天':'')+String(h).padStart(2,'0')+':'+String(m).padStart(2,'0')+':'+String(s).padStart(2,'0');}
