function showAt(){var sel=$('atSel');if(!sel)return;if(!me){sel.style.display='none';return;}try{api('/rest/v1/profiles?select=nickname,id&role=eq.admin&limit=50').then(function(admins){api('/rest/v1/followers?select=following_id&follower_id=eq.'+me.id+'&limit=200').then(function(follows){var list=[];if(admins)list=list.concat(admins.filter(function(a){return a.id!==me.id;}));if(follows&&follows.length){var ids=follows.map(function(f){return f.following_id;});api('/rest/v1/profiles?select=nickname,id&id=in.('+ids.join(',')+')').then(function(fs){if(fs)list=list.concat(fs.filter(function(f){return f.id!==me.id;}));list=list.filter(function(v,i,a){return a.findIndex(function(x){return x.id===v.id;})===i;});sel.innerHTML=list.length?list.map(function(u){return'<div class="at-i" onclick="insertAt(\''+esc(u.nickname)+'\')">@'+esc(u.nickname)+'</div>';}).join(''):'<div class="at-i">可@管理员及关注的人</div>';sel.style.display='block';});}else{sel.innerHTML='<div class="at-i">可@管理员及关注的人</div>';sel.style.display='block';}}).catch(function(){sel.innerHTML='<div class="at-i">可@管理员及关注的人</div>';sel.style.display='block';});}).catch(function(){sel.style.display='none';});}catch(e){sel.style.display='none';}}
