function pickResType(el,k){resType=k;document.querySelectorAll('#resTypeChips .chip').forEach(function(x){x.classList.remove('on');});el.classList.add('on');var rv=$('resPostVideo'),ra=$('resPostApp');if(rv)rv.style.display=k==='video'?'block':'none';if(ra)ra.style.display=k==='app'?'block':'none';}
async function submitRes(){if(!me||me.role!=='admin'){toast('仅管理员');return;}var title,desc,link,size=null,icon='';if(resType==='video'){var rt=$('resTitle'),rd=$('resDesc'),rl=$('resLink');if(!rt||!rd||!rl)return;title=rt.value.trim();desc=rd.value.trim();link=(rl.dataset&&rl.dataset.link)||rl.value.trim();if(!title||!link){var re=$('resErr');if(re)re.textContent='请填标题和链接';return;}}else{var rt2=$('resTitle'),rd2=$('resDesc2'),rl2=$('resLink2');if(!rt2||!rd2||!rl2)return;title=rt2.value.trim();desc=rd2.value.trim();link=(rl2.dataset&&rl2.dataset.link)||rl2.value.trim();if(!title||!link){var re2=$('resErr');if(re2)re2.textContent='请填标题和链接';return;}var rs=$('resSize');if(rs)size=rs.value.trim()||null;}try{await dbI('resources',{title:title,description:desc,type:resType,link:link,icon:icon,size_mb:size,created_by:me.id});toast('✅已发布');var all=[$('resTitle'),$('resDesc'),$('resLink'),$('resDesc2'),$('resLink2'),$('resSize')];all.forEach(function(el){if(el){el.value='';el.dataset&&(el.dataset.link='');}});goPage('resourcePage');}catch(e){var re3=$('resErr');if(re3)re3.textContent='失败：'+e.message;}}
async function loadRes(type){resType=type;try{var rt1=$('resTab1'),rt2=$('resTab2');if(rt1)rt1.classList.toggle('on',type==='video');if(rt2)rt2.classList.toggle('on',type==='app');}catch(e){}var rl=$('resList');if(!rl)return;rl.innerHTML='<div class="empty">加载中...</div>';try{var d=await api('/rest/v1/resources?select=*&type=eq.'+type+'&order=created_at.desc');if(!d||!d.length){rl.innerHTML='<div class="empty">暂无内容</div>';return;}var isAdmin=me&&me.role==='admin';if(type==='video'){rl.innerHTML=d.map(function(r){return'<div class="video-card"><div class="video-cover" onclick="window.open(\''+esc(r.link)+'\')">▶️</div><div class="video-info"><div class="vt">'+esc(r.title)+'</div><div class="vs">'+esc(r.description||'')+'</div>'+(isAdmin?'<div style="margin-top:4px"><span style="color:#e5484d;font-size:11px;cursor:pointer" onclick="delRes('+r.id+')">🗑删除</span></div>':'')+'</div></div>';}).join('');}else{rl.innerHTML=d.map(function(r){return'<div class="app-card" onclick="openAppDetail('+r.id+')"><div class="ac-top"><div class="ac-icon" style="background:#eee;text-align:center;line-height:48px;font-size:22px">'+(r.icon?'<img src="'+esc(r.icon)+'" class="ac-icon">':'📱')+'</div><div><div class="ac-title">'+esc(r.title)+'<span class="lv" style="margin-left:4px;background:#ff9500">'+(r.size_mb||'')+'</span></div><div class="ac-sub">'+esc(r.description||'')+'·📥'+(r.downloads||0)+'次</div>'+(isAdmin?'<div style="margin-top:4px"><span style="color:#e5484d;font-size:11px;cursor:pointer" onclick="event.stopPropagation();delRes('+r.id+')">🗑删除</span></div>':'')+'</div></div></div>';}).join('');}}catch(e){rl.innerHTML='<div class="empty">加载失败</div>';}}
async function delRes(rid){if(!confirm('确定删除？'))return;try{await dbD('resources','id=eq.'+rid);toast('已删除');loadRes(resType);}catch(e){toast('失败');}}
async function openAppDetail(id){try{var r=await api('/rest/v1/resources?id=eq.'+id);var d=r&&r[0];if(!d)return;var fav=me?await isFav('app',d.id):false;var ab=$('appDetailBox');if(!ab)return;ab.innerHTML='<div style="background:#fff;border-radius:12px;padding:16px;text-align:center;margin-bottom:10px">'+(d.icon?'<img src="'+esc(d.icon)+'" style="width:72px;height:72px;border-radius:14px;object-fit:cover;margin-bottom:8px">':'<div style="width:72px;height:72px;border-radius:14px;background:#eee;line-height:72px;margin:0 auto 8px;font-size:28px">📱</div>')+'<div style="font-size:17px;font-weight:700">'+esc(d.title)+'</div></div><div style="background:#fff;border-radius:12px;padding:14px;font-size:13px;line-height:1.7;color:#444;margin-bottom:10px">'+esc(d.description||'暂无介绍')+'</div><div class="stat-card"><div><div class="stat-num">'+(d.downloads||0)+'</div><div class="stat-label">下载</div></div><div><div class="stat-num">'+(d.size_mb||'--')+'</div><div class="stat-label">大小</div></div></div><div class="detail-actions"><button class="action-btn '+(fav?'on':'')+'" style="border-color:#7B68EE;color:#7B68EE" onclick="favRes(\'app\','+d.id+')">⭐'+(fav?'已收藏':'收藏')+'</button><button class="action-btn" style="border-color:#ff9500;color:#ff9500" onclick="window.open(\''+esc(d.link)+'\')">🔗前往下载</button>'+(me&&me.role==='admin'?'<button class="action-btn" style="color:#e5484d" onclick="delRes('+d.id+')">🗑删除</button>':'')+'</div>';goPage('appDetailPage');}catch(e){toast('加载失败');}}
async function favRes(type,rid){if(!me){toast('请先登录');needLogin();return;}try{var r=await api('/rest/v1/favorites?user_id=eq.'+me.id+'&target_type=eq.'+type+'&target_id=eq.'+rid+'&limit=1');if(r&&r.length){await dbD('favorites','user_id=eq.'+me.id+'&target_type=eq.'+type+'&target_id=eq.'+rid);toast('已取消');}else{await dbI('favorites',{user_id:me.id,target_type:type,target_id:rid});toast('⭐已收藏');}loadRes(resType);}catch(e){toast('失败');}}
async function loadAdmin(tab){try{var a1=$('aTab1'),a2=$('aTab2');if(a1)a1.classList.toggle('on',tab==='reports');if(a2)a2.classList.toggle('on',tab==='punish');}catch(e){}var ab=$('adminBox');if(!ab)return;if(tab==='reports'){try{var d=await api('/rest/v1/reports?status=eq.pending&order=created_at.desc');if(!d||!d.length){ab.innerHTML='<div class="empty">没有待处理举报🎉</div>';return;}var h='<div class="tip" style="margin-bottom:8px">共'+d.length+'条</div>';for(var i=0;i<d.length;i++){var r=d[i],target='',content='',author='';try{if(r.target_type==='post'){var p=await api('/rest/v1/posts?select=*,author_id(nickname)&id=eq.'+r.target_id);if(p&&p[0]){target='帖子：'+p[0].title;content=p[0].content;author=p[0].author_id?p[0].author_id.nickname:'';}}else{var c=await api('/rest/v1/comments?select=*,author_id(nickname)&id=eq.'+r.target_id);if(c&&c[0]){target='评论#'+r.target_id;content=c[0].content;author=c[0].author_id?c[0].author_id.nickname:'';}}}catch(e){}h+='<div class="comment-box"><div style="font-size:13px;font-weight:600">🚩'+esc(r.reason)+'</div><div style="font-size:11px;color:#999;margin:4px 0">'+esc(target)+' · 作者：'+esc(author)+'</div><div style="font-size:12px;color:#555;background:#f7f8fa;border-radius:8px;padding:8px;margin:8px 0;cursor:pointer" onclick="'+(r.target_type==='post'?'openPost('+r.target_id+')':'')+'">'+esc(content)+'</div><div style="display:flex;gap:8px"><button class="btn" style="background:#999;flex:1" onclick="handleReport('+r.id+',\'ignore\')">忽略</button><button class="btn" style="flex:1" onclick="handleReport('+r.id+',\'delete\')">删内容</button><button class="btn" style="background:#e5484d;flex:1" onclick="handleReport('+r.id+',\'punish\')">删+扣分</button></div></div>';}ab.innerHTML=h;}catch(e){ab.innerHTML='<div class="empty">加载失败</div>';}}else{ab.innerHTML='<div class="tip" style="margin-bottom:8px">按用户名或QQ号查找用户</div><input id="punishQQ" class="inp" placeholder="输入用户名或QQ号"><button class="btn" onclick="findUser()">查找</button><div id="userInfo" style="margin-top:10px"></div><div style="margin-top:12px;background:#fff;border-radius:10px;padding:12px"><div style="font-size:13px;font-weight:600;margin-bottom:8px">📢 群发通知</div><textarea id="broadcastText" class="inp" style="height:50px" placeholder="通知内容"></textarea><div style="display:flex;gap:8px"><button class="btn" style="flex:1" onclick="broadcast(\'all\')">发给全体</button><button class="btn btn-plain" style="flex:1" onclick="broadcast(\'admins\')">发给管理员</button></div></div>';}}
async function broadcast(t){var bt=$('broadcastText');if(!bt)return;var c=bt.value.trim();if(!c){toast('请输入通知内容');return;}try{var r=await dbR('broadcast_notification',{p_content:c,p_target:t});toast(r==='OK'?'✅已群发':r);bt.value='';}catch(e){toast('失败');}}
async function findUser(){var pq=$('punishQQ');if(!pq)return;var kw=pq.value.trim();try{var d;if(/^\d{5,12}$/.test(kw)){d=await api('/rest/v1/profiles?select=*&qq=eq.'+kw+'&limit=1');}else{d=await api('/rest/v1/profiles?select=*&nickname=eq.'+kw+'&limit=1');}var ui=$('userInfo');if(!ui)return;if(!d||!d.length){ui.innerHTML='<div class="empty">没找到</div>';return;}var u=d[0];ui.innerHTML='<div class="comment-box"><div style="font-weight:600">👤'+esc(u.nickname)+(u.role==='admin'?'<span class="tag-admin">管理</span>':'')+'</div><div style="font-size:12px;color:#555;background:#f7f8fa;border-radius:8px;padding:8px;margin:6px 0">QQ：'+esc(u.qq||'-')+' · Lv'+u.level+'·🪙'+u.coins+'·💯'+u.credit+(u.is_banned?'·⛔已封号':'')+'</div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn" style="background:#e5484d" onclick="punish(\''+u.id+'\',\'credit\',prompt(\'扣多少分？\',\'10\'))">扣分</button><button class="btn" onclick="punish(\''+u.id+'\',\'mute\',prompt(\'禁言几天？\',\'1\'))">禁言</button><button class="btn" style="background:#e5484d" onclick="punish(\''+u.id+'\',\'ban\',0)">封号</button><button class="btn" style="background:#e5484d" onclick="punish(\''+u.id+'\',\'device_ban\',0)">封设备</button><button class="btn" style="background:#999" onclick="punish(\''+u.id+'\',\'unban\',0)">解封</button><button class="btn" style="background:#999" onclick="punish(\''+u.id+'\',\'unmute\',0)">解禁</button><button class="btn" style="background:#999" onclick="punish(\''+u.id+'\',\'unde\',0)">解封设备</button><button class="btn" style="background:#07c160" onclick="punish(\''+u.id+'\',\'addcredit\',prompt(\'加多少分？\',\'5\'))">加信誉分</button><button class="btn" style="background:#07c160" onclick="punish(\''+u.id+'\',\'addcoin\',prompt(\'给多少硬币？\',\'10\'))">奖硬币</button></div></div>';}catch(e){var ui2=$('userInfo');if(ui2)ui2.innerHTML='<div class="empty">查询失败</div>';}}
async function punish(uid,action,amount){try{var r=await dbR('admin_punish',{p_user_id:uid,p_action:action,p_amount:parseInt(amount)||0,p_detail:action});toast(r==='OK'?'✅已执行':('⚠️'+r));}catch(e){toast('失败');}}
async function handleReport(rid,act){try{if(act==='ignore'){await dbU('reports','id=eq.'+rid,{status:'ignored'});toast('已忽略');}else{var r=await api('/rest/v1/reports?id=eq.'+rid);var rep=r&&r[0];if(rep){if(rep.target_type==='post'){var p=await api('/rest/v1/posts?id=eq.'+rep.target_id);if(p&&p[0]){if(act==='punish')await dbR('admin_punish',{p_user_id:p[0].author_id,p_action:'credit',p_amount:10,p_detail:'举报成立'});await dbR('delete_post',{pid:rep.target_id});}}else{await dbR('delete_comment',{cid:rep.target_id});}await dbU('reports','id=eq.'+rid,{status:'handled'});if(rep.reporter_id)dbR('reward_report',{p_reporter_id:rep.reporter_id}).catch(function(){});toast('✅已处理');}}loadAdmin('reports');}catch(e){toast('处理失败');}}
try{drawCaptcha();}catch(e){}
try{if(curUser2())showMain();else goPage('loginPage');}catch(e){goPage('loginPage');}